import React, { useEffect, useState } from 'react'
import TreatmentSheetDetails from './TreatmentSheetDetails'
import useApi from '../../../../hooks/useApi'
import dependantsApi from '../../../../api/dependantsApi'
import { toast, ToastContainer } from 'react-toastify'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { useLocation } from 'react-router-dom'
import { useStateContext } from '../../../../contexts/ContextProvider'
import PrescriptionsPage from '../../visitors/PrescriptionsPage'

export default function TreatmentSheet() {
  const {loggedInUser} = useStateContext()

  const [selectedAdmission, setselectedAdmission] = useState()
  const [selectedDependant, setselectedDependant] = useState()
  const [dischargeSummary, setdischargeSummary] = useState()
  const [errors, setErrors] = useState([])
  const [showForm, setshowForm] = useState(dischargeSummary ? false : true)

  const [updated, setupdated] = useState(false)
  const location = useLocation()
  const [selectedDependantId, setselectedDependantId] = useState()
  useEffect(() => {
      setselectedDependantId(location.state.dependant)
  }, [location])



  //Get admission

  const getAdmissionApi = useApi(hospitalsApi.hospitalInpatientAction)
  const getDependantAdmission = async (id) => {
      await getAdmissionApi.request({
          "action": "GetDependantAdmission",
          "dependant": id
      })
  }

  useEffect(() => {
      if (errors && errors.length) {
          errors.map((x) => {
              toast.error(x);
          });
      }
  }, [errors]);
  useEffect(() => {
      if (getAdmissionApi.data) {

          if (getAdmissionApi.data.admission) {
              setselectedAdmission(getAdmissionApi.data.admission)
              toast.success(getAdmissionApi.data.response_message)
          }
      }

      console.log("getAdmissionApi.data", getAdmissionApi.data)
  }, [getAdmissionApi.data])


  const getDependantDetailsApi = useApi(dependantsApi.dependantsAction)
  const getDependantDetails = async (id) => {
      await getDependantDetailsApi.request({
          "action": "GetDependantDetails",
          "dependant_id": id
      })
  }


  useEffect(()=>{
      if(getDependantDetailsApi.data){
          if(getDependantDetailsApi.data.dependant){
              setselectedDependant(getDependantDetailsApi.data.dependant)
              toast.success(getDependantDetailsApi.data.response_message)
          }
      }
      console.log("getDependantDetailsApi.data",getDependantDetailsApi.data)
  },[getDependantDetailsApi.data])


  useEffect(() => {
      if (selectedDependantId) {
          getDependantAdmission(selectedDependantId)
          getDependantDetails(selectedDependantId);
          console.log("selectedDependantId",selectedDependantId)
      }

  }, [selectedDependantId])

  useEffect(() => {
      if (selectedAdmission) {
        
          // getAdmissionOrCreatePrescription(selectedAdmission.id);
         
      }

  }, [selectedAdmission])



  return (
    <div className='w-full'>
    <p className='text-xl text-center font-semibold'>Treatment Sheet</p>

    <ToastContainer theme='light' position='bottom-center'/>
     {selectedAdmission? <TreatmentSheetDetails selectedAdmission={selectedAdmission} />:<div></div>}

      {selectedAdmission && selectedDependant && <PrescriptionsPage selectedAdmission={selectedAdmission} selectedDependant={selectedDependant} nature="INPATIENT" title="Inpatient Prescription"/>}

    </div>
  )
}
