import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi';
import hospitalsApi from '../../../../api/hospitals/hospitalsApi';
import { Table } from 'antd';
import TreatmentSheetModal from './TreatmentSheetModal';

export default function TreatmentSheetDetails({ selectedAdmission }) {

    const columns = [
        {
            title: "Date",
            dataIndex: "created",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Title",
            dataIndex: "title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Route",
            dataIndex: "route_title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Dose",
            dataIndex: "dose",
        },
        {
            title: "Frequency",
            dataIndex: "frequency_title",
        },
        {
            title: "Days",
            dataIndex: "days",
        },
        {
            title: "Progress",
            dataIndex: "administration_progresss",
        },

    ];
    const [admissionPrescriptionItems, setadmissionPrescriptionItems] = useState([])
    const [data, setData] = useState([])
    const [ismodalOpen, setismodalOpen] = useState(false)

    const getAdmissionPrescriptionItemsApi = useApi(hospitalsApi.hospitalStaffAction)
    const [selectedAdmissionPrescriptionItem, setselectedAdmissionPrescriptionItem] = useState()

    const getAdmissionPrescriptionItems = async () => {

        await getAdmissionPrescriptionItemsApi.request({
            "action": "GetAdmissionPrescriptionItems",
            "admission": selectedAdmission.id
        })
    }

    useEffect(() => {
        if (admissionPrescriptionItems) {
            setData(admissionPrescriptionItems)
        }
    }, [admissionPrescriptionItems])


    useEffect(() => {
        if (getAdmissionPrescriptionItemsApi.data) {

            if (getAdmissionPrescriptionItemsApi.data.length) {
                setadmissionPrescriptionItems(getAdmissionPrescriptionItemsApi.data)
            }
        }
        console.log("getAdmissionPrescriptionItemsApi.data", getAdmissionPrescriptionItemsApi.data)
    }, [getAdmissionPrescriptionItemsApi.data])


    useEffect(() => {
        if (selectedAdmission) {
            getAdmissionPrescriptionItems();
        }
    }, [selectedAdmission])


    const [selectedRowKeys, setSelectedRowKeys] = useState([]);

    const onSelectChange = (newSelectedRowKeys, selectedRows) => {
        console.log("selectedRowKeys changed: ", newSelectedRowKeys);
        setSelectedRowKeys(newSelectedRowKeys);
        setselectedAdmissionPrescriptionItem(selectedRows[0]);
    };

    const rowSelection = {
        selectedRowKeys,
        onChange: onSelectChange,
    };

    useEffect(() => {
        if (selectedAdmissionPrescriptionItem) {
            setismodalOpen(true)
        }
    }, [selectedAdmissionPrescriptionItem])
    return (
        <div>
            {selectedAdmissionPrescriptionItem && selectedAdmissionPrescriptionItem.administrations && selectedAdmissionPrescriptionItem.administrations.length ? <TreatmentSheetModal ismodalOpen={ismodalOpen} setismodalOpen={setismodalOpen} selectedAdmissionPrescriptionItem={selectedAdmissionPrescriptionItem} setselectedAdmissionPrescriptionItem={setselectedAdmissionPrescriptionItem} /> : <div></div>}
            <Table
                rowSelection={{
                    type: "radio",
                    ...rowSelection,
                }}
                columns={columns}
                dataSource={data}
            />


        </div>
    )
}
